import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# CUDA source: kernel + PyBind11 wrapper
cuda_source = r'''
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>

extern "C" __global__
void rmsnorm_forward(const half* __restrict__ x, half* __restrict__ y,
                     int batch, int features, int inner, float eps) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = batch * inner;
    if (idx >= total) return;

    int b = idx / inner;
    int i = idx % inner;

    const half* in_ptr  = x + b * features * inner + i;
    half*       out_ptr = y + b * features * inner + i;

    float sum = 0.0f;
#pragma unroll
    for (int c = 0; c < features; ++c) {
        half v = in_ptr[c * inner];
        float f = __half2float(v);
        sum += f * f;
    }

    float mean = sum / static_cast<float>(features);
    float rms  = sqrtf(mean + eps);
    float inv  = 1.0f / rms;

#pragma unroll
    for (int c = 0; c < features; ++c) {
        half v = in_ptr[c * inner];
        float f = __half2float(v);
        out_ptr[c * inner] = __float2half(f * inv);
    }
}

void rmsnorm_forward_cuda(torch::Tensor x, torch::Tensor y,
                          int batch, int features, int inner, float eps) {
    const int threads = 256;
    const dim3 block(threads);
    const dim3 grid((batch * inner + threads - 1) / threads);

    rmsnorm_forward<<<grid, block>>>(
        reinterpret_cast<const half*>(x.data_ptr()),
        reinterpret_cast<half*>(y.data_ptr()),
        batch, features, inner, eps
    );

    cudaError_t err = cudaGetLastError();
    if (err != cudaSuccess) {
        throw std::runtime_error(cudaGetErrorString(err));
    }
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("rmsnorm_forward", &rmsnorm_forward_cuda,
          "RMSNorm forward (CUDA)");
}
'''

# Compile the inline extension
rmsnorm_cuda = load_inline(
    name="rmsnorm_cuda",
    cpp_sources=cuda_source,
    functions=["rmsnorm_forward"],
    verbose=False,
)

class ModelNew(nn.Module):
    """
    Drop‑in replacement of the reference RMSNorm using a custom CUDA kernel.
    """
    def __init__(self, num_features: int, eps: float = 1e-5):
        super().__init__()
        self.num_features = num_features
        self.eps = eps

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # Expect fp16, contiguous tensor
        assert x.dtype == torch.float16, "Input must be torch.float16"
        assert x.is_contiguous(), "Input must be contiguous"

        batch = x.size(0)
        features = x.size(1)
        # product of all dimensions after the feature axis
        inner = x[0, 0].numel()

        y = torch.empty_like(x)
        rmsnorm_cuda.rmsnorm_forward(
            x,
            y,
            batch,
            features,
            inner,
            float(self.eps)
        )
        return y

# Helper functions matching the reference script
def get_inputs():
    # Example shapes (can be changed by the harness)
    batch_size = 112
    features = 64
    dim1 = 512
    dim2 = 512
    x = torch.rand(batch_size, features, dim1, dim2, dtype=torch.float16, device='cuda')
    return [x]

def get_init_inputs():
    # Only the number of features is needed for construction
    return [64]

# Expose the model class for external use
__all__ = ["ModelNew", "get_inputs", "get_init_inputs"]
